import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int mod = Integer.parseInt(st.nextToken());

        long phi = computeEuler(mod);
        int maxLen = n + 5;
        long[] factorials = new long[maxLen + 1];
        factorials[0] = 1;
        for (int i = 1; i <= maxLen; i++) {
            factorials[i] = (factorials[i - 1] * i) % mod;
        }

        if (n <= 3) {
            System.out.println(0);
            return;
        }

        long[] dp = new long[2000];
        dp[0] = 1;
        dp[1] = 2;
        dp[2] = 2;
        dp[3] = 1;

        int size = buildSegmentTree(2005);
        long[] tree = new long[size];
        for (int i = 0; i < 4; i++) {
            modify(tree, size, i, dp[i]);
        }

        int m = 3;
        long totalAns = 0;

        for (int i = 0; i < n - 3; i++) {
            long[] prevDp = Arrays.copyOf(dp, dp.length);
            long partialSum = 0;
            for (int j = 0; j <= i + 2; j++) {
                for (int k = 1; k <= m + 1; k++) {
                    long rangeSumVal = rangeSum(tree, size, j + k + 1, 2004);
                    partialSum = (partialSum + rangeSumVal * prevDp[k - 1]) % mod;
                    long newVal = (dp[j + k] + prevDp[k - 1]) % mod;
                    dp[j + k] = newVal;
                    modify(tree, size, j + k, newVal);
                }
            }
            m += i + 3;
            long factorialPart = factorialMod(i + 4, n, mod, factorials);
            totalAns = (totalAns + factorialPart * partialSum) % mod;
        }

        System.out.println(totalAns);
    }

    static int buildSegmentTree(int size) {
        int i = 2;
        while (true) {
            if (i >= size * 2) {
                return i;
            }
            i *= 2;
        }
    }

    static void modify(long[] tree, int size, int i, long x) {
        int idx = i + size / 2;
        tree[idx] = x;
        idx /= 2;
        while (idx > 0) {
            tree[idx] = tree[2 * idx] + tree[2 * idx + 1];
            idx /= 2;
        }
    }

    static long rangeSum(long[] tree, int size, int s, int t) {
        s += size / 2;
        t += size / 2;
        long total = 0;
        while (s <= t) {
            if (s % 2 == 0) {
                s /= 2;
            } else {
                total += tree[s];
                s = (s + 1) / 2;
            }
            if (t % 2 == 1) {
                total += tree[t];
                t = (t - 1) / 2;
            } else {
                t /= 2;
            }
        }
        return total;
    }

    static List<Long> primeFactors(long n) {
        List<Long> factors = new ArrayList<>();
        for (long i = 2; i * i <= n; i++) {
            while (n % i == 0) {
                factors.add(i);
                n /= i;
            }
            if (n == 1) {
                break;
            }
        }
        if (n != 1) {
            factors.add(n);
        }
        return factors;
    }

    static long computeEuler(long n) {
        Set<Long> pFactors = new HashSet<>(primeFactors(n));
        long result = n;
        for (long p : pFactors) {
            result = result * (p - 1) / p;
        }
        return result;
    }

    static long factorialMod(int a, int b, int mod, long[] factorials) {
        long res = 1;
        for (int i = a; i <= b; i++) {
            res = (res * i) % mod;
        }
        return res;
    }
}
